-- Database wilayah Indonesia dari kodepos.extended.json
-- MySQL / MariaDB
-- ID menggunakan VARCHAR karena format kode wilayah mengandung titik.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP VIEW IF EXISTS `v_wilayah_lengkap`;
DROP TABLE IF EXISTS `master_kelurahan_desa`;
DROP TABLE IF EXISTS `master_kecamatan`;
DROP TABLE IF EXISTS `master_kabupaten_kota`;
DROP TABLE IF EXISTS `master_provinsi`;

CREATE TABLE `master_provinsi` (
  `id` VARCHAR(2) NOT NULL,
  `nama` VARCHAR(150) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_provinsi_nama` (`nama`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `master_kabupaten_kota` (
  `id` VARCHAR(5) NOT NULL,
  `provinsi_id` VARCHAR(2) NOT NULL,
  `nama` VARCHAR(180) NOT NULL,
  `tipe` ENUM('Kabupaten','Kota') DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_kabkota_provinsi` (`provinsi_id`),
  KEY `idx_kabkota_nama` (`nama`),
  CONSTRAINT `fk_kabkota_provinsi` FOREIGN KEY (`provinsi_id`) REFERENCES `master_provinsi` (`id`) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `master_kecamatan` (
  `id` VARCHAR(8) NOT NULL,
  `kabupaten_kota_id` VARCHAR(5) NOT NULL,
  `nama` VARCHAR(180) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_kecamatan_kabkota` (`kabupaten_kota_id`),
  KEY `idx_kecamatan_nama` (`nama`),
  CONSTRAINT `fk_kecamatan_kabkota` FOREIGN KEY (`kabupaten_kota_id`) REFERENCES `master_kabupaten_kota` (`id`) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `master_kelurahan_desa` (
  `id` VARCHAR(13) NOT NULL,
  `kecamatan_id` VARCHAR(8) NOT NULL,
  `nama` VARCHAR(220) NOT NULL,
  `kode_pos` VARCHAR(5) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_kelurahan_kecamatan` (`kecamatan_id`),
  KEY `idx_kelurahan_nama` (`nama`),
  KEY `idx_kelurahan_kode_pos` (`kode_pos`),
  CONSTRAINT `fk_kelurahan_kecamatan` FOREIGN KEY (`kecamatan_id`) REFERENCES `master_kecamatan` (`id`) ON UPDATE CASCADE ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;


























































































































































































COMMIT;

CREATE VIEW `v_wilayah_lengkap` AS
SELECT
  kd.id AS kelurahan_desa_id,
  kd.nama AS kelurahan_desa,
  kd.kode_pos,
  kc.id AS kecamatan_id,
  kc.nama AS kecamatan,
  kk.id AS kabupaten_kota_id,
  kk.nama AS kabupaten_kota,
  kk.tipe AS tipe_kabupaten_kota,
  p.id AS provinsi_id,
  p.nama AS provinsi
FROM master_kelurahan_desa kd
JOIN master_kecamatan kc ON kc.id = kd.kecamatan_id
JOIN master_kabupaten_kota kk ON kk.id = kc.kabupaten_kota_id
JOIN master_provinsi p ON p.id = kk.provinsi_id;

SET FOREIGN_KEY_CHECKS=1;

-- Contoh: gunakan ID kelurahan/desa sebagai patokan utama
-- SELECT * FROM v_wilayah_lengkap WHERE kelurahan_desa_id = '11.01.01.2001';
